PRAGMA foreign_keys = ON;

CREATE TABLE workspace_roots (uid TEXT PRIMARY KEY, singleton INTEGER NOT NULL DEFAULT 1 UNIQUE CHECK(singleton=1), created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
INSERT INTO workspace_roots(uid) VALUES (lower(hex(randomblob(16))));
CREATE TABLE templates (uid TEXT PRIMARY KEY, kind TEXT NOT NULL CHECK(kind IN ('OBJECT','ARTIFACT')), name TEXT NOT NULL, created_by TEXT NOT NULL, created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE template_versions (uid TEXT PRIMARY KEY, template_uid TEXT NOT NULL REFERENCES templates(uid), kind TEXT NOT NULL CHECK(kind IN ('OBJECT','ARTIFACT')), name TEXT NOT NULL, version_number INTEGER NOT NULL CHECK(version_number > 0), state TEXT NOT NULL CHECK(state IN ('DRAFT','PUBLISHED','DISABLED')), initial_state TEXT NOT NULL, created_by TEXT NOT NULL, created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP, published_at TEXT, UNIQUE(template_uid, version_number));
CREATE TABLE template_create_roles (template_version_uid TEXT NOT NULL REFERENCES template_versions(uid), role_code TEXT NOT NULL, PRIMARY KEY(template_version_uid, role_code));
CREATE TABLE field_definitions (uid TEXT PRIMARY KEY, template_version_uid TEXT NOT NULL REFERENCES template_versions(uid), field_key TEXT NOT NULL, field_type TEXT NOT NULL CHECK(field_type IN ('string','multiline_text','integer','decimal','boolean','date','datetime','single_select','multi_select','user_reference','object_reference','artifact_reference')), required INTEGER NOT NULL CHECK(required IN (0,1)), searchable INTEGER NOT NULL CHECK(searchable IN (0,1)), linkable INTEGER NOT NULL CHECK(linkable IN (0,1)), printable INTEGER NOT NULL CHECK(printable IN (0,1)), relevant_for_review INTEGER NOT NULL CHECK(relevant_for_review IN (0,1)), historized INTEGER NOT NULL CHECK(historized IN (0,1)), editable INTEGER NOT NULL CHECK(editable IN (0,1)), visible INTEGER NOT NULL CHECK(visible IN (0,1)), position INTEGER NOT NULL, UNIQUE(template_version_uid, field_key));
CREATE TABLE field_options (field_definition_uid TEXT NOT NULL REFERENCES field_definitions(uid), option_value TEXT NOT NULL, position INTEGER NOT NULL, PRIMARY KEY(field_definition_uid, option_value));
CREATE TABLE child_definitions (template_version_uid TEXT NOT NULL REFERENCES template_versions(uid), child_key TEXT NOT NULL, child_template_version_uid TEXT NOT NULL REFERENCES template_versions(uid), min_count INTEGER NOT NULL DEFAULT 0 CHECK(min_count >= 0), max_count INTEGER CHECK(max_count IS NULL OR max_count >= min_count), auto_create INTEGER NOT NULL CHECK(auto_create IN (0,1)), mode TEXT NOT NULL CHECK(mode IN ('FIXED','MAINTENANCE','FLEXIBLE')), position INTEGER NOT NULL, PRIMARY KEY(template_version_uid, child_key));
CREATE TABLE lifecycle_states (uid TEXT PRIMARY KEY, template_version_uid TEXT NOT NULL REFERENCES template_versions(uid), state_code TEXT NOT NULL, is_initial INTEGER NOT NULL DEFAULT 0 CHECK(is_initial IN (0,1)), UNIQUE(template_version_uid, state_code));
CREATE TABLE lifecycle_transitions (uid TEXT PRIMARY KEY, template_version_uid TEXT NOT NULL REFERENCES template_versions(uid), from_state_code TEXT NOT NULL, to_state_code TEXT NOT NULL, reason_required INTEGER NOT NULL DEFAULT 0 CHECK(reason_required IN (0,1)), signature_required INTEGER NOT NULL DEFAULT 0 CHECK(signature_required IN (0,1)), UNIQUE(template_version_uid, from_state_code, to_state_code));
CREATE TABLE lifecycle_transition_roles (transition_uid TEXT NOT NULL REFERENCES lifecycle_transitions(uid), role_code TEXT NOT NULL, PRIMARY KEY(transition_uid, role_code));
CREATE TABLE module_blueprints (uid TEXT PRIMARY KEY, blueprint_key TEXT NOT NULL UNIQUE, name TEXT NOT NULL, description TEXT NOT NULL, root_template_version_uid TEXT NOT NULL REFERENCES template_versions(uid), published_by TEXT NOT NULL, published_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE module_blueprint_templates (module_blueprint_uid TEXT NOT NULL REFERENCES module_blueprints(uid), template_key TEXT NOT NULL, template_version_uid TEXT NOT NULL REFERENCES template_versions(uid), is_root INTEGER NOT NULL CHECK(is_root IN (0,1)), PRIMARY KEY(module_blueprint_uid,template_key), UNIQUE(module_blueprint_uid,template_version_uid));
CREATE TABLE objects (uid TEXT PRIMARY KEY, template_version_uid TEXT NOT NULL REFERENCES template_versions(uid), parent_kind TEXT NOT NULL CHECK(parent_kind IN ('WORKSPACE_ROOT','OBJECT')), parent_uid TEXT NOT NULL, depth INTEGER NOT NULL CHECK(depth BETWEEN 1 AND 32), state TEXT NOT NULL, revision INTEGER NOT NULL CHECK(revision >= 1), fixed INTEGER NOT NULL DEFAULT 0 CHECK(fixed IN (0,1)), archived INTEGER NOT NULL DEFAULT 0 CHECK(archived IN (0,1)), archived_at TEXT, archived_by TEXT, created_by TEXT NOT NULL, created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP, updated_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE INDEX idx_objects_parent ON objects(parent_kind, parent_uid);
CREATE TABLE object_field_values (object_uid TEXT NOT NULL REFERENCES objects(uid), field_definition_uid TEXT NOT NULL REFERENCES field_definitions(uid), string_value TEXT, integer_value INTEGER, decimal_value TEXT, boolean_value INTEGER CHECK(boolean_value IN (0,1)), date_value TEXT, datetime_value TEXT, user_uid TEXT, object_uid_value TEXT, artifact_uid_value TEXT, PRIMARY KEY(object_uid, field_definition_uid));
CREATE TABLE object_field_value_history (id INTEGER PRIMARY KEY, object_uid TEXT NOT NULL, field_definition_uid TEXT NOT NULL, changed_by TEXT NOT NULL, changed_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP, string_value TEXT, integer_value INTEGER, decimal_value TEXT, boolean_value INTEGER, date_value TEXT, datetime_value TEXT, user_uid TEXT, object_uid_value TEXT, artifact_uid_value TEXT);
CREATE TABLE artifacts (uid TEXT PRIMARY KEY, template_version_uid TEXT NOT NULL REFERENCES template_versions(uid), owner_object_uid TEXT NOT NULL REFERENCES objects(uid), state TEXT NOT NULL, revision INTEGER NOT NULL CHECK(revision >= 1), immutable INTEGER NOT NULL DEFAULT 0 CHECK(immutable IN (0,1)), archived INTEGER NOT NULL DEFAULT 0 CHECK(archived IN (0,1)), final_snapshot_uid TEXT, finalized_at TEXT, created_by TEXT NOT NULL, created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE artifact_field_values (artifact_uid TEXT NOT NULL REFERENCES artifacts(uid), field_definition_uid TEXT NOT NULL REFERENCES field_definitions(uid), string_value TEXT, integer_value INTEGER, decimal_value TEXT, boolean_value INTEGER, date_value TEXT, datetime_value TEXT, user_uid TEXT, object_uid_value TEXT, artifact_uid_value TEXT, PRIMARY KEY(artifact_uid, field_definition_uid));
CREATE TABLE artifact_field_value_history (id INTEGER PRIMARY KEY, artifact_uid TEXT NOT NULL, field_definition_uid TEXT NOT NULL, changed_by TEXT NOT NULL, changed_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP, string_value TEXT, integer_value INTEGER, decimal_value TEXT, boolean_value INTEGER, date_value TEXT, datetime_value TEXT, user_uid TEXT, object_uid_value TEXT, artifact_uid_value TEXT);
CREATE TABLE artifact_files (uid TEXT PRIMARY KEY, artifact_uid TEXT NOT NULL REFERENCES artifacts(uid), relative_path TEXT NOT NULL, original_name TEXT NOT NULL, media_type TEXT NOT NULL, size_bytes INTEGER NOT NULL CHECK(size_bytes >= 0), content_hash TEXT NOT NULL, immutable INTEGER NOT NULL DEFAULT 0 CHECK(immutable IN (0,1)), created_by TEXT NOT NULL, created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP, UNIQUE(artifact_uid, relative_path));
CREATE TABLE artifact_snapshots (uid TEXT PRIMARY KEY, artifact_uid TEXT NOT NULL REFERENCES artifacts(uid), state_hash TEXT NOT NULL, template_version_uid TEXT NOT NULL REFERENCES template_versions(uid), artifact_state TEXT NOT NULL, artifact_revision INTEGER NOT NULL, created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP, UNIQUE(artifact_uid));
CREATE TABLE artifact_snapshot_field_values (snapshot_uid TEXT NOT NULL REFERENCES artifact_snapshots(uid), field_definition_uid TEXT NOT NULL REFERENCES field_definitions(uid), string_value TEXT, integer_value INTEGER, decimal_value TEXT, boolean_value INTEGER CHECK(boolean_value IN (0,1)), date_value TEXT, datetime_value TEXT, user_uid TEXT, object_uid_value TEXT, artifact_uid_value TEXT, PRIMARY KEY(snapshot_uid, field_definition_uid));
CREATE TABLE artifact_snapshot_files (snapshot_uid TEXT NOT NULL REFERENCES artifact_snapshots(uid), artifact_file_uid TEXT NOT NULL, relative_path TEXT NOT NULL, original_name TEXT NOT NULL, media_type TEXT NOT NULL, size_bytes INTEGER NOT NULL CHECK(size_bytes >= 0), content_hash TEXT NOT NULL, PRIMARY KEY(snapshot_uid, artifact_file_uid));
CREATE TABLE artifact_snapshot_references (snapshot_uid TEXT NOT NULL REFERENCES artifact_snapshots(uid), reference_uid TEXT NOT NULL, source_kind TEXT NOT NULL, source_uid TEXT NOT NULL, target_kind TEXT NOT NULL, target_uid TEXT NOT NULL, link_type_uid TEXT, PRIMARY KEY(snapshot_uid, reference_uid));
CREATE TABLE artifact_corrections (corrected_artifact_uid TEXT PRIMARY KEY REFERENCES artifacts(uid), original_artifact_uid TEXT NOT NULL REFERENCES artifacts(uid), created_by TEXT NOT NULL, created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP, CHECK(corrected_artifact_uid <> original_artifact_uid));
CREATE TABLE object_snapshots (uid TEXT PRIMARY KEY, object_uid TEXT NOT NULL REFERENCES objects(uid), state_hash TEXT NOT NULL, template_version_uid TEXT NOT NULL REFERENCES template_versions(uid), object_state TEXT NOT NULL, object_revision INTEGER NOT NULL, parent_kind TEXT NOT NULL CHECK(parent_kind IN ('WORKSPACE_ROOT','OBJECT')), parent_uid TEXT NOT NULL, depth INTEGER NOT NULL CHECK(depth BETWEEN 1 AND 32), created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE object_snapshot_field_values (snapshot_uid TEXT NOT NULL REFERENCES object_snapshots(uid), field_definition_uid TEXT NOT NULL REFERENCES field_definitions(uid), string_value TEXT, integer_value INTEGER, decimal_value TEXT, boolean_value INTEGER, date_value TEXT, datetime_value TEXT, user_uid TEXT, object_uid_value TEXT, artifact_uid_value TEXT, PRIMARY KEY(snapshot_uid, field_definition_uid));
CREATE TABLE object_snapshot_references (snapshot_uid TEXT NOT NULL REFERENCES object_snapshots(uid), reference_uid TEXT NOT NULL, source_kind TEXT NOT NULL, source_uid TEXT NOT NULL, target_kind TEXT NOT NULL, target_uid TEXT NOT NULL, link_type_uid TEXT NOT NULL, PRIMARY KEY(snapshot_uid, reference_uid));
CREATE TABLE signatures (uid TEXT PRIMARY KEY, artifact_uid TEXT REFERENCES artifacts(uid), object_uid TEXT REFERENCES objects(uid), snapshot_uid TEXT, state_hash TEXT NOT NULL, signer_user_id TEXT NOT NULL, meaning TEXT NOT NULL, signed_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP, revoked_at TEXT, CHECK((artifact_uid IS NOT NULL) OR (object_uid IS NOT NULL)), UNIQUE(snapshot_uid, signer_user_id));
CREATE TABLE link_types (uid TEXT PRIMARY KEY, code TEXT NOT NULL UNIQUE, source_kind TEXT NOT NULL, target_kind TEXT NOT NULL, inverse_label TEXT);
CREATE TABLE references_table (uid TEXT PRIMARY KEY, source_kind TEXT NOT NULL, source_uid TEXT NOT NULL, target_kind TEXT NOT NULL, target_uid TEXT NOT NULL, link_type_uid TEXT REFERENCES link_types(uid), created_by TEXT NOT NULL, created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP, UNIQUE(source_kind, source_uid, target_kind, target_uid, link_type_uid));
CREATE TABLE external_reference_targets (uid TEXT PRIMARY KEY, source_kind TEXT NOT NULL, source_uid TEXT NOT NULL, provider_code TEXT NOT NULL, module_code TEXT NOT NULL, entity_uid TEXT NOT NULL, mode TEXT NOT NULL CHECK(mode IN ('FIXED','DYNAMIC')), fixed_version_uid TEXT, created_by TEXT NOT NULL, created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP, CHECK((mode='FIXED' AND fixed_version_uid IS NOT NULL) OR (mode='DYNAMIC' AND fixed_version_uid IS NULL)));
CREATE TABLE external_reference_resolutions (uid TEXT PRIMARY KEY, external_reference_target_uid TEXT NOT NULL REFERENCES external_reference_targets(uid), resolved_version_uid TEXT NOT NULL, resolved_by TEXT NOT NULL, resolved_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE acl_entries (uid TEXT PRIMARY KEY, aggregate_kind TEXT NOT NULL, aggregate_uid TEXT NOT NULL, subject_user_id TEXT, subject_role_code TEXT, permission_code TEXT NOT NULL, CHECK(subject_user_id IS NOT NULL OR subject_role_code IS NOT NULL));
CREATE TABLE audit_events (uid TEXT PRIMARY KEY, event_type TEXT NOT NULL, aggregate_uid TEXT NOT NULL, actor_user_id TEXT NOT NULL, occurred_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE audit_event_details (id INTEGER PRIMARY KEY, audit_event_uid TEXT NOT NULL REFERENCES audit_events(uid), detail_key TEXT NOT NULL, detail_value TEXT NOT NULL, UNIQUE(audit_event_uid, detail_key));
CREATE TABLE backup_evidence (uid TEXT PRIMARY KEY, scope_uid TEXT NOT NULL, integrity_hash TEXT NOT NULL, created_by TEXT NOT NULL, created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE physical_deletion_approvals (uid TEXT PRIMARY KEY, object_uid TEXT NOT NULL, requester_user_id TEXT NOT NULL, approved_by TEXT NOT NULL, approved_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP, CHECK(requester_user_id <> approved_by), UNIQUE(object_uid,requester_user_id,approved_by));
CREATE TABLE tombstones (uid TEXT PRIMARY KEY, deleted_entity_uid TEXT NOT NULL, deleted_entity_kind TEXT NOT NULL, backup_evidence_uid TEXT REFERENCES backup_evidence(uid), deletion_approval_uid TEXT REFERENCES physical_deletion_approvals(uid), deleted_by TEXT NOT NULL, reason TEXT NOT NULL, deleted_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE exports (uid TEXT PRIMARY KEY, root_object_uid TEXT NOT NULL REFERENCES objects(uid), manifest_hash TEXT NOT NULL, created_by TEXT NOT NULL, include_artifacts INTEGER NOT NULL CHECK(include_artifacts IN (0,1)), include_files INTEGER NOT NULL CHECK(include_files IN (0,1)), printable INTEGER NOT NULL CHECK(printable IN (0,1)), created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE export_items (export_uid TEXT NOT NULL REFERENCES exports(uid), item_kind TEXT NOT NULL CHECK(item_kind IN ('OBJECT','ARTIFACT','FILE')), item_uid TEXT NOT NULL, content_hash TEXT, PRIMARY KEY(export_uid,item_kind,item_uid));
CREATE TABLE template_migrations (uid TEXT PRIMARY KEY, object_uid TEXT NOT NULL, old_template_version_uid TEXT NOT NULL REFERENCES template_versions(uid), new_template_version_uid TEXT NOT NULL REFERENCES template_versions(uid), migrated_by TEXT NOT NULL, migrated_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP, CHECK(old_template_version_uid <> new_template_version_uid));
CREATE TABLE template_migration_fields (template_migration_uid TEXT NOT NULL REFERENCES template_migrations(uid), field_key TEXT NOT NULL, old_field_definition_uid TEXT REFERENCES field_definitions(uid), new_field_definition_uid TEXT NOT NULL REFERENCES field_definitions(uid), was_compatible INTEGER NOT NULL CHECK(was_compatible IN (0,1)), PRIMARY KEY(template_migration_uid,field_key));
CREATE TABLE deletion_policies (uid TEXT PRIMARY KEY, scope TEXT NOT NULL CHECK(scope IN ('GLOBAL','TEMPLATE')), scope_key TEXT NOT NULL, template_version_uid TEXT REFERENCES template_versions(uid), require_backup INTEGER NOT NULL CHECK(require_backup IN (0,1)), require_second_approver INTEGER NOT NULL CHECK(require_second_approver IN (0,1)), configured_by TEXT NOT NULL, configured_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP, UNIQUE(scope,scope_key), CHECK((scope='GLOBAL' AND scope_key='' AND template_version_uid IS NULL) OR (scope='TEMPLATE' AND scope_key=template_version_uid AND template_version_uid IS NOT NULL)));
CREATE TABLE deletion_policy_roles (policy_uid TEXT NOT NULL REFERENCES deletion_policies(uid), role_code TEXT NOT NULL, PRIMARY KEY(policy_uid,role_code));
CREATE TABLE outbox_events (uid TEXT PRIMARY KEY, event_name TEXT NOT NULL, aggregate_uid TEXT NOT NULL, actor_user_id TEXT NOT NULL, created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP, published_at TEXT);
CREATE TRIGGER objects_parent_insert BEFORE INSERT ON objects BEGIN
  SELECT CASE WHEN NEW.parent_kind='WORKSPACE_ROOT' AND NOT EXISTS(SELECT 1 FROM workspace_roots WHERE uid=NEW.parent_uid) THEN RAISE(ABORT, 'workspace root parent missing') END;
  SELECT CASE WHEN NEW.parent_kind='OBJECT' AND NOT EXISTS(SELECT 1 FROM objects WHERE uid=NEW.parent_uid) THEN RAISE(ABORT, 'object parent missing') END;
END;
CREATE TRIGGER objects_parent_update BEFORE UPDATE OF parent_kind,parent_uid ON objects BEGIN
  SELECT CASE WHEN NEW.parent_kind='WORKSPACE_ROOT' AND NOT EXISTS(SELECT 1 FROM workspace_roots WHERE uid=NEW.parent_uid) THEN RAISE(ABORT, 'workspace root parent missing') END;
  SELECT CASE WHEN NEW.parent_kind='OBJECT' AND NOT EXISTS(SELECT 1 FROM objects WHERE uid=NEW.parent_uid) THEN RAISE(ABORT, 'object parent missing') END;
END;
